Here is src/store.rs. What does `append` guarantee if the process is killed halfway through a write?

```rust
use std::fs::{File, OpenOptions};
use std::io::{self, BufRead, BufReader, Write};
use std::path::{Path, PathBuf};

pub struct Store {
    path: PathBuf,
    file: File,
    entries: u64,
}

impl Store {
    pub fn open(path: &Path) -> io::Result<Store> {
        let file = OpenOptions::new().create(true).append(true).read(true).open(path)?;
        let entries = BufReader::new(File::open(path)?).lines().count() as u64;
        Ok(Store { path: path.to_path_buf(), file, entries })
    }

    pub fn append(&mut self, record: &str) -> io::Result<u64> {
        assert!(!record.contains('\n'), "a record is one line");
        self.file.write_all(record.as_bytes())?;
        self.file.write_all(b"\n")?;
        self.entries += 1;
        Ok(self.entries)
    }

    pub fn replay(&self) -> io::Result<Vec<String>> {
        let reader = BufReader::new(File::open(&self.path)?);
        reader.lines().collect()
    }
}
