Right. Now src/account.rs. Why can `withdraw` leave a negative balance under concurrent use?

```rust
use std::collections::HashMap;
use std::sync::{Arc, Mutex};

#[derive(Clone, Default)]
pub struct Accounts {
    balances: Arc<Mutex<HashMap<String, i64>>>,
}

impl Accounts {
    pub fn balance(&self, id: &str) -> i64 {
        *self.balances.lock().unwrap().get(id).unwrap_or(&0)
    }

    pub fn deposit(&self, id: &str, amount: i64) {
        let mut map = self.balances.lock().unwrap();
        *map.entry(id.to_string()).or_insert(0) += amount;
    }

    pub fn withdraw(&self, id: &str, amount: i64) -> Result<(), String> {
        if self.balance(id) < amount {
            return Err(format!("{id}: insufficient funds"));
        }
        let mut map = self.balances.lock().unwrap();
        *map.entry(id.to_string()).or_insert(0) -= amount;
        Ok(())
    }
}
