Next, src/transfer.rs. A transfer is supposed to be all-or-nothing. Point out every way it is not.

```rust
use crate::account::Accounts;
use crate::store::Store;

pub struct Transfer<'a> {
    pub from: &'a str,
    pub to: &'a str,
    pub amount: i64,
}

pub fn apply(accounts: &Accounts, store: &mut Store, t: &Transfer<'_>) -> Result<u64, String> {
    if t.amount <= 0 {
        return Err("amount must be positive".into());
    }
    if t.from == t.to {
        return Err("cannot transfer to the same account".into());
    }
    accounts.withdraw(t.from, t.amount)?;
    accounts.deposit(t.to, t.amount);
    let line = format!("{}\t{}\t{}", t.from, t.to, t.amount);
    store.append(&line).map_err(|e| e.to_string())
}

pub fn replay(accounts: &Accounts, store: &Store) -> Result<usize, String> {
    let lines = store.replay().map_err(|e| e.to_string())?;
    for line in &lines {
        let mut parts = line.split('\t');
        let from = parts.next().ok_or("missing from")?;
        let to = parts.next().ok_or("missing to")?;
        let amount: i64 = parts.next().ok_or("missing amount")?.parse().map_err(|_| "bad amount")?;
        accounts.withdraw(from, amount)?;
        accounts.deposit(to, amount);
    }
    Ok(lines.len())
}
