use serde::Deserialize;

#[derive(Deserialize)]
pub struct TransferBody {
    pub from: String,
    pub to: String,
    pub amount: f64,
}

pub fn parse_amount(body: &TransferBody) -> Result<i64, String> {
    if !body.amount.is_finite() {
        return Err("amount must be finite".into());
    }
    let cents = (body.amount * 100.0).round();
    if cents <= 0.0 {
        return Err("amount must be positive".into());
    }
    Ok(cents as i64)
}
